//! Sample contract where the interesting code is generated by a macro.
//!
//! Small Soroban contracts do this a lot: you write the transfer logic
//! once in a macro_rules! and stamp it out wherever you need it. The
//! catch for a scanner is that `payout` below never appears as a plain
//! function in the source - it only exists once the macro expands.
//!
//! Expected findings: AP-AUTH-001 and AP-CALL-001 on the generated
//! `payout` (it moves tokens with no require_auth anywhere), plus the
//! file-level AP-STORAGE-001 because nothing here extends TTL.

use soroban_sdk::{contract, contractimpl, token, Address, Env};

macro_rules! make_payout {
    () => {
        pub fn payout(env: Env, token: Address, to: Address, amount: i128) {
            let client = token::Client::new(&env, &token);
            client.transfer(&env.current_contract_address(), &to, &amount);
            env.storage().persistent().set(&to, &amount);
        }
    };
}

#[contract]
pub struct MacroVault;

#[contractimpl]
impl MacroVault {
    // Stamps out `payout` from the macro above.
    make_payout!();
}
